// Authoring source for the A1 extension. The deployed app reads the generated JSON directly.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { a1Test } from './a1_exam_content.mjs';
import { curriculumDocument } from './a1_curriculum_document.mjs';
import { workshops } from './a1_workshop_content.mjs';
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const pair = (de, en) => ({ de, en });
const vocab = (rows) => rows.map(([de, en, pl]) => ({ de, en, ...(pl ? { pl } : {}) }));
const choice = (question, options, answer, hint, extra = {}) => ({ type: 'choice', question, options, answer, hint, ...extra });
const fill = (question, answer, hint) => ({ type: 'fill', question, answers: [answer], hint });
const order = (question, sentence, hint) => ({ type: 'order', question, words: sentence.split(' '), answers: [sentence], hint });
const listen = (audioText, question, options, answer) => ({ type: 'listen', audioText, question, options, answer, englishOptions: true, hint: 'Listen for the requested detail; a familiar word alone does not make an option correct.' });
const write = (question, modelAnswer) => ({ type: 'write', question, modelAnswer });
const lessons = [];
function lesson(id, title, germanTitle, intro, head, rows, rules, examples, words, tasks, reading) {
  lessons.push({ id, title, germanTitle, intro, table: { head, rows }, rules, examples: examples.map(([de, en]) => pair(de, en)), vocab: vocab(words), tasks: [...tasks, ...(reading ? [choice(reading[1], reading[2], reading[3], reading[4], { readingText: reading[0], englishOptions: true })] : [])] });
}

lesson(9, 'German sounds, the alphabet and spelling', 'Laute und Alphabet',
  'Learn how written German becomes speech. Begin with clear, understandable sounds, then spell your name and ask for repetition. You do not need to sound like a native speaker.',
  ['Spelling', 'Sound or example'], [['ei', 'mein, drei'], ['ie', 'sieben, wie'], ['eu / äu', 'neun, Häuser'], ['sch / sp / st', 'Schule, sprechen, Straße'], ['ch', 'ich / Buch: two different sounds'], ['ä / ö / ü', 'März, schön, fünf']],
  ['Listen, pause, repeat, then say the example without reading. Use short groups of words.', 'German letter names differ from English ones. Practise a complete alphabet recording; pay special attention to E, G, J, V, W and Z.', 'A long vowel and a short vowel can change a word: practise bieten / bitten and Stadt / Staat with a speaker.', 'Pronounce the end of a word clearly. Final b, d and g often sound like p, t and k.', 'Ask for help: Bitte langsam. Noch einmal, bitte. Können Sie das bitte buchstabieren?'],
  [['Wie schreibt man Ihren Namen?', 'How do you spell your name?'], ['Mein Name ist Weber: W, E, B, E, R.', 'My name is Weber: W, E, B, E, R.'], ['Können Sie das bitte wiederholen?', 'Can you repeat that, please?'], ['Bitte sprechen Sie langsam.', 'Please speak slowly.']],
  [['buchstabieren', 'to spell'], ['wiederholen', 'to repeat'], ['langsam', 'slowly'], ['der Buchstabe', 'letter', 'Buchstaben'], ['der Name', 'name', 'Namen'], ['die Sprache', 'language', 'Sprachen'], ['verstehen', 'to understand'], ['sprechen', 'to speak']],
  [choice('Which spelling usually has a long ee sound?', ['ei', 'ie', 'eu'], 1, 'ie usually represents a long vowel, as in sieben.'), fill('Bitte sprechen Sie ___. (slowly)', 'langsam', 'Ask for a slower pace.'), order('Build a polite request to repeat.', 'Können Sie das bitte wiederholen', 'Können is first in this yes/no question; wiederholen finishes it.'), listen('Guten Tag. Mein Name ist Lena Berg. Berg schreibt man B, E, R, G.', 'What is the surname?', ['Berg', 'Berger', 'Beck'], 0), write('Write two polite sentences asking for repetition and spelling.', 'Können Sie das bitte wiederholen? Können Sie das bitte buchstabieren?')],
  ['Anmeldung: Bitte schreiben Sie Ihren Namen deutlich. Schreiben Sie auch Ihre Telefonnummer. Bei Fragen sprechen Sie mit Frau Weber.', 'What information is requested?', ['Name and phone number', 'Nationality only', 'Exam result'], 0, 'Look for the two fields: Namen and Telefonnummer.']);

lesson(10, 'Numbers, prices and contact details', 'Zahlen und Kontakt',
  'Say numbers accurately and recognise them in speech. Use them for age, prices, telephone numbers, house numbers and postcodes.',
  ['Number', 'German'], [['13 / 30', 'dreizehn / dreißig'], ['16 / 60', 'sechzehn / sechzig'], ['21 / 34', 'einundzwanzig / vierunddreißig'], ['100 / 1,000', 'hundert / tausend'], ['€ 2,50', 'zwei Euro fünfzig'], ['Telephone digits', 'null, eins, zwei, drei …']],
  ['For 21–99 say the units before the tens, joined by und.', 'Practise -zehn and -zig as contrasting pairs so that 14 and 40 stay distinct.', 'Give telephone numbers and postcodes digit by digit when clarity matters.', 'German prices usually use a decimal comma. € 3,80 is drei Euro achtzig.', 'Age: Ich bin … Jahre alt. Contact details: Meine Telefonnummer ist …'],
  [['Ich bin vierundzwanzig Jahre alt.', 'I am twenty-four years old.'], ['Das kostet drei Euro achtzig.', 'That costs three euros eighty.'], ['Meine Hausnummer ist siebzehn.', 'My house number is seventeen.'], ['Wie ist Ihre Telefonnummer?', 'What is your phone number?']],
  [['die Zahl', 'number', 'Zahlen'], ['die Nummer', 'number or identifier', 'Nummern'], ['die Adresse', 'address', 'Adressen'], ['die Telefonnummer', 'phone number', 'Telefonnummern'], ['die Postleitzahl', 'postcode', 'Postleitzahlen'], ['kosten', 'to cost'], ['alt', 'old'], ['der Euro', 'euro', 'Euro']],
  [fill('21 heißt ___.', 'einundzwanzig', 'Units + und + tens.'), choice('Which number is sechzig?', ['16', '60', '6'], 1, 'Listen for -zig.'), order('Build the question: How old are you?', 'Wie alt bist du', 'Wie alt comes before the verb.'), listen('Das Brot kostet zwei Euro fünfzig. Der Saft kostet einen Euro neunzig.', 'What does the bread cost?', ['€ 2.50', '€ 1.90', '€ 2.90'], 0), write('Invent a safe example profile with age, house number and telephone number.', 'Ich bin 28 Jahre alt. Meine Hausnummer ist 12. Meine Telefonnummer ist 0176 2048 3159.')],
  ['Kontakt: Nina Wolf, Gartenstraße 18, 04109 Leipzig. Telefon: 0341 582019. Bitte rufen Sie am Nachmittag an.', 'What is the house number?', ['18', '04109', '582019'], 0, 'Identify the number after the street name.']);

lesson(11, 'Personal details and registration forms', 'Persönliche Daten',
  'Give personal information and transfer information from a short profile to a form. Distinguish name, nationality, birthplace, current home and contact details.',
  ['Form field', 'Meaning'], [['Vorname / Familienname', 'first name / surname'], ['Geburtsdatum / Geburtsort', 'date / place of birth'], ['Wohnort / Straße', 'current town / street'], ['Staatsangehörigkeit', 'nationality'], ['Familienstand', 'marital status'], ['Unterschrift', 'signature']],
  ['Complete a form from the profile supplied in the task, even when the information differs from your own.', 'Use sein for age and nationality, kommen aus for origin and wohnen in for the current town.', 'Dates in German usually follow day, month, year: 12.03.2001.', 'Country names without an article take aus: aus Indien. Learn article phrases as units: aus der Türkei, aus der Schweiz, aus den USA.', 'Keep questions and answers in the same register: du with bist, Sie with sind.'],
  [['Ich komme aus Indien und wohne in Bremen.', 'I come from India and live in Bremen.'], ['Meine Muttersprache ist Hindi.', 'My first language is Hindi.'], ['Ich bin ledig.', 'I am single.'], ['Wie ist Ihr Familienname?', 'What is your surname?']],
  [['der Vorname', 'first name', 'Vornamen'], ['der Familienname', 'surname', 'Familiennamen'], ['das Geburtsdatum', 'date of birth', 'Geburtsdaten'], ['der Geburtsort', 'place of birth', 'Geburtsorte'], ['der Wohnort', 'town of residence', 'Wohnorte'], ['ledig', 'single'], ['verheiratet', 'married'], ['die Unterschrift', 'signature', 'Unterschriften']],
  [choice('Which field asks where you live now?', ['Geburtsort', 'Wohnort', 'Vorname'], 1, 'Geburtsort is where you were born.'), fill('Ich komme ___ der Türkei.', 'aus', 'Learn aus der Türkei as a complete phrase.'), order('Ask for a surname politely.', 'Wie ist Ihr Familienname', 'Use Ihr with a formal address.'), listen('Mein Name ist Omar Ali. Ich komme aus Ägypten, aber ich wohne jetzt in Bonn.', 'Where does Omar live now?', ['Egypt', 'Bonn', 'Berlin'], 1), write('Write a four-sentence personal profile. Include origin, current town, language and marital status.', 'Ich komme aus Kanada. Ich wohne in Hamburg. Ich spreche Englisch und Deutsch. Ich bin verheiratet.')],
  ['Mila Novak ist am 14. Juni 1998 in Prag geboren. Sie wohnt jetzt in Köln und ist ledig. Ihre Telefonnummer ist 0221 450871.', 'What goes in the Geburtsort field?', ['Köln', 'Prag', 'ledig'], 1, 'The birthplace and the current town are different.']);

lesson(12, 'Family, possession and describing people', 'Familie und Besitz',
  'Introduce family members and say whose things they are. Use possessive words together with the noun gender and plural.',
  ['Owner', 'Masculine / neuter', 'Feminine / plural'], [['ich', 'mein', 'meine'], ['du', 'dein', 'deine'], ['er / es', 'sein', 'seine'], ['sie', 'ihr', 'ihre'], ['wir', 'unser', 'unsere'], ['Sie', 'Ihr', 'Ihre']],
  ['Possessive words take endings: mein Vater, meine Mutter, mein Kind, meine Eltern.', 'For a masculine object in the accusative use -en: Ich besuche meinen Bruder.', 'A name can show possession with -s: Annas Schwester. Recognise this without learning a full genitive system.', 'Describe people with sein + adjective: Meine Schwester ist freundlich. Predicate adjectives have no noun ending here.', 'Use haben to describe family: Ich habe zwei Kinder.'],
  [['Das ist meine Schwester.', 'That is my sister.'], ['Unser Sohn ist zehn Jahre alt.', 'Our son is ten years old.'], ['Ich besuche meinen Vater.', 'I visit my father.'], ['Lenas Bruder wohnt in Berlin.', 'Lena’s brother lives in Berlin.']],
  [['die Eltern', 'parents', 'pl'], ['der Sohn', 'son', 'Söhne'], ['die Tochter', 'daughter', 'Töchter'], ['der Bruder', 'brother', 'Brüder'], ['die Schwester', 'sister', 'Schwestern'], ['freundlich', 'friendly'], ['besuchen', 'to visit'], ['zusammen', 'together']],
  [fill('Das ist ___ Mutter. (my)', 'meine', 'Mutter is feminine.'), choice('Choose the correct form: Ich besuche ___ Bruder.', ['mein', 'meine', 'meinen'], 2, 'Bruder is a masculine object.'), order('Say: Our daughter is nine years old.', 'Unsere Tochter ist neun Jahre alt', 'The verb stays in position two.'), listen('Ich habe einen Bruder und zwei Schwestern. Meine Eltern wohnen in Wien.', 'How many sisters does the speaker have?', ['One', 'Two', 'Three'], 1), write('Describe two family members in four short sentences.', 'Meine Mutter heißt Eva. Sie ist freundlich. Mein Bruder heißt Paul. Er wohnt in Bonn.')],
  ['Ich heiße Tim. Meine Frau heißt Sara. Wir haben eine Tochter, Mia. Sie ist fünf Jahre alt. Meine Eltern wohnen nicht bei uns.', 'Who is Mia?', ['Tim’s wife', 'Tim’s daughter', 'Tim’s mother'], 1, 'Tochter means daughter.']);

lesson(13, 'Questions, pronouns and irregular present verbs', 'Fragen und Verben',
  'Ask for information and respond with a full short answer. Practise important present-tense stem changes rather than guessing from the regular pattern.',
  ['Question or verb', 'Example'], [['wer / was', 'Wer ist das? Was brauchst du?'], ['wo / woher / wohin', 'Wo wohnst du? Wohin fährst du?'], ['wann / wie / wie viel', 'Wann kommst du? Wie viel kostet das?'], ['sprechen / essen', 'du sprichst / du isst'], ['lesen / sehen', 'du liest / du siehst'], ['fahren / nehmen', 'du fährst / du nimmst']],
  ['W-questions put the question word before the conjugated verb. Yes/no questions start with the verb.', 'Several common verbs change their stem for du and er/sie/es: sprechen → sprichst/spricht.', 'The stem normally stays unchanged for wir and formal Sie: wir sprechen, Sie sprechen.', 'Subject pronouns include ich, du, er, sie, es, wir, ihr and sie/Sie.', 'Answer a question for its meaning: Wo? needs a place; Wann? needs a time.'],
  [['Welche Sprachen sprichst du?', 'Which languages do you speak?'], ['Er liest eine Zeitung.', 'He reads a newspaper.'], ['Fährst du heute nach Berlin?', 'Are you travelling to Berlin today?'], ['Was nimmst du?', 'What are you taking?']],
  [['wer', 'who'], ['was', 'what'], ['wann', 'when'], ['wohin', 'where to'], ['welche', 'which'], ['lesen', 'to read'], ['nehmen', 'to take'], ['die Zeitung', 'newspaper', 'Zeitungen']],
  [fill('Du ___ Deutsch. (sprechen)', 'sprichst', 'sprechen changes e to i for du.'), choice('Choose a question about time.', ['Wo wohnst du?', 'Wann kommst du?', 'Wer ist das?'], 1, 'Wann asks when.'), order('Ask: Are you reading the newspaper?', 'Liest du die Zeitung', 'The verb comes first in a yes/no question.'), listen('Heute fahre ich nach Erfurt. Der Zug fährt um zehn Uhr. Ich komme am Abend zurück.', 'When does the train leave?', ['In the evening', 'At ten', 'At eleven'], 1), write('Write two W-questions and two yes/no questions about a classmate.', 'Wo wohnst du? Welche Sprachen sprichst du? Arbeitest du heute? Trinkst du gern Tee?')],
  ['Deutschgruppe: Treffen am Dienstag um 18 Uhr. Wir lesen kurze Texte und sprechen Deutsch. Neue Teilnehmer sind willkommen.', 'What does the group do?', ['Read and speak German', 'Buy newspapers only', 'Meet every morning'], 0, 'Identify the activities rather than only the day.']);

lesson(14, 'Daily routines, frequency and dates', 'Mein Alltag',
  'Explain your week and understand schedules. Combine a time expression with a present-tense action, and recognise frequent date phrases.',
  ['Expression', 'Use'], [['immer / oft / manchmal / nie', 'always / often / sometimes / never'], ['am Montag / am Morgen', 'on Monday / in the morning'], ['im Januar / im Sommer', 'in January / in summer'], ['um acht Uhr', 'at eight o’clock'], ['von neun bis fünf', 'from nine to five'], ['am dritten Mai', 'on the third of May']],
  ['A time phrase may come first, but the verb remains second: Am Montag arbeite ich.', 'Use am with weekdays and many parts of the day, im with months and seasons, um with clock times.', 'Know date forms you need for appointments: am ersten, zweiten, dritten …; recognise them in speech.', 'Use von … bis … for opening hours and working periods.', 'Give a routine first, then one exception: Normalerweise …, aber heute …'],
  [['Ich arbeite oft am Samstag.', 'I often work on Saturdays.'], ['Im Sommer fahren wir nach Italien.', 'In summer we travel to Italy.'], ['Der Kurs ist am dritten Mai.', 'The course is on the third of May.'], ['Heute habe ich frei.', 'Today I have the day off.']],
  [['oft', 'often'], ['manchmal', 'sometimes'], ['nie', 'never'], ['normalerweise', 'normally'], ['der Alltag', 'everyday life', '-'], ['der Feiertag', 'public holiday', 'Feiertage'], ['frei', 'free; off work'], ['beginnen', 'to begin']],
  [fill('Der Kurs beginnt ___ neun Uhr.', 'um', 'Clock times use um.'), choice('Which means never?', ['oft', 'nie', 'immer'], 1, 'nie is the opposite of immer.'), order('Start with the time: On Monday I work.', 'Am Montag arbeite ich', 'The subject comes after the verb when time comes first.'), listen('Die Praxis ist am Dienstag von acht bis zwölf Uhr geöffnet. Am Nachmittag ist sie geschlossen.', 'When is the practice open on Tuesday?', ['8–12', '12–18', 'All day'], 0), write('Write four sentences about your week. Include a day, a clock time and a frequency word.', 'Am Montag arbeite ich. Ich beginne um neun Uhr. Am Abend lese ich oft. Am Sonntag habe ich frei.')],
  ['Sprachkurs: Montag und Mittwoch, 18–20 Uhr. Im August gibt es keinen Unterricht. Der nächste Kurs beginnt am 2. September.', 'Is there a class in August?', ['Yes, every day', 'No', 'Only on Friday'], 1, 'kein Unterricht tells you there are no classes.']);

lesson(15, 'Food, quantities and ordering politely', 'Essen bestellen',
  'Order food, ask for quantities and express a simple preference. Learn useful polite phrases as complete expressions.',
  ['Function', 'Phrase'], [['Ordering', 'Ich hätte gern einen Tee.'], ['Requesting', 'Ein Glas Wasser, bitte.'], ['Preference', 'Ich esse gern Gemüse.'], ['Quantity', 'ein Kilo / ein Liter / eine Flasche'], ['Paying', 'Die Rechnung, bitte.'], ['Alternative', 'Tee oder Kaffee?']],
  ['Treat Ich hätte gern as a useful fixed phrase at A1; a full Konjunktiv II lesson is unnecessary here.', 'For a masculine thing you order use einen: einen Kaffee. Feminine uses eine; neuter uses ein.', 'Food substances often have no article: Ich kaufe Brot und Milch.', 'gern means you enjoy doing something: Ich trinke gern Tee.', 'Be ready to respond to a choice: Lieber Tee, bitte.'],
  [['Ich hätte gern eine Suppe.', 'I would like a soup.'], ['Ich nehme einen Salat.', 'I will have a salad.'], ['Zwei Flaschen Wasser, bitte.', 'Two bottles of water, please.'], ['Können wir bitte bezahlen?', 'Can we pay, please?']],
  [['die Rechnung', 'bill', 'Rechnungen'], ['die Flasche', 'bottle', 'Flaschen'], ['das Glas', 'glass', 'Gläser'], ['die Suppe', 'soup', 'Suppen'], ['der Salat', 'salad', 'Salate'], ['bezahlen', 'to pay'], ['lieber', 'preferably'], ['das Gemüse', 'vegetables', '-']],
  [fill('Ich nehme ___ Kaffee.', 'einen', 'Kaffee is masculine and is the object.'), choice('Which politely asks for the bill?', ['Die Rechnung, bitte.', 'Ich bin die Rechnung.', 'Die Rechnung wohnt hier.'], 0, 'A short noun phrase with bitte is a useful request.'), order('Order a soup politely.', 'Ich hätte gern eine Suppe', 'Learn this polite expression as a unit.'), listen('Für mich eine Suppe und ein Glas Wasser, bitte. Mein Freund nimmt einen Salat und einen Tee.', 'What does the speaker order to drink?', ['Tea', 'Water', 'Coffee'], 1), write('Write a short order for two people and ask to pay.', 'Ich hätte gern eine Suppe und einen Tee. Mein Freund nimmt einen Salat und ein Wasser. Können wir bitte bezahlen?')],
  ['Mittagsangebot: Suppe 4 Euro, Salat 6 Euro, Kaffee 2 Euro. Das Angebot gilt von 12 bis 14 Uhr. Kartenzahlung ist möglich.', 'When is the lunch offer available?', ['10–12', '12–14', '14–18'], 1, 'Find the time range after gilt.']);

lesson(16, 'Shopping, clothes and prices', 'Einkaufen',
  'Ask a shop assistant about prices, colours and sizes. Understand a simple advertisement and compare items with familiar phrases.',
  ['Question', 'Answer'], [['Was kostet die Jacke?', 'Sie kostet 35 Euro.'], ['Welche Größe brauchen Sie?', 'Größe 40, bitte.'], ['Haben Sie die Jacke in Blau?', 'Ja, hier bitte.'], ['Kann ich mit Karte bezahlen?', 'Ja, natürlich.'], ['Wie finden Sie die Jacke?', 'Sie ist schön, aber zu teuer.']],
  ['Use dieser/diese/dieses to point to a known item: diese Jacke, dieses Hemd.', 'Predicate colours and adjectives stay unchanged: Die Jacke ist blau.', 'Use es for a neuter noun, sie for a feminine noun and er for a masculine noun.', 'Learn comparisons as useful phrases: größer, kleiner, billiger, lieber. Full adjective declension comes later.', 'Ask for help politely and respond when an item is unavailable.'],
  [['Diese Jacke ist zu groß.', 'This jacket is too big.'], ['Haben Sie das Hemd in Weiß?', 'Do you have the shirt in white?'], ['Kann ich mit Karte bezahlen?', 'Can I pay by card?'], ['Ich nehme diese Tasche.', 'I will take this bag.']],
  [['die Größe', 'size', 'Größen'], ['die Jacke', 'jacket', 'Jacken'], ['das Hemd', 'shirt', 'Hemden'], ['die Tasche', 'bag', 'Taschen'], ['die Karte', 'card', 'Karten'], ['teuer', 'expensive'], ['billig', 'cheap'], ['passen', 'to fit']],
  [fill('___ Jacke ist schön. (this)', 'Diese', 'Jacke is feminine.'), choice('The assistant asks Welche Größe? What should you answer?', ['Größe 38.', 'Am Montag.', 'Aus Spanien.'], 0, 'Give a clothing size.'), order('Ask whether you can pay by card.', 'Kann ich mit Karte bezahlen', 'The infinitive goes at the end.'), listen('Die blaue Tasche kostet zwanzig Euro. Die rote Tasche kostet fünfzehn Euro.', 'What does the red bag cost?', ['€ 20', '€ 15', '€ 50'], 1), write('Write three questions to a shop about an item, its price and payment.', 'Haben Sie diese Jacke in Blau? Was kostet sie? Kann ich mit Karte bezahlen?')],
  ['Fahrrad zu verkaufen: 70 Euro. Farbe: rot. Abholung nur am Samstag. Bitte rufen Sie ab 18 Uhr an.', 'When can the buyer collect the bicycle?', ['Every day', 'Saturday only', 'After 18:00 only on Friday'], 1, 'Separate the collection day from the telephone time.']);

lesson(17, 'Abilities, obligations and permissions', 'Modalverben',
  'Say what you can, want or must do, and understand permission or prohibition. Build the sentence bracket with a modal verb and an infinitive.',
  ['Verb', 'ich', 'du', 'er / sie', 'wir / Sie'], [['können', 'kann', 'kannst', 'kann', 'können'], ['müssen', 'muss', 'musst', 'muss', 'müssen'], ['wollen', 'will', 'willst', 'will', 'wollen'], ['dürfen', 'darf', 'darfst', 'darf', 'dürfen'], ['sollen', 'soll', 'sollst', 'soll', 'sollen'], ['möchten', 'möchte', 'möchtest', 'möchte', 'möchten']],
  ['The conjugated modal takes position two; the other verb stays in the infinitive at the end.', 'In a yes/no question the modal is first: Kannst du morgen kommen?', 'nicht dürfen means not allowed to; nicht müssen means not necessary. These are different.', 'Use sollen for an instruction or advice received from someone else: Ich soll anrufen.', 'Use möchten to make a polite wish.'],
  [['Ich kann Deutsch sprechen.', 'I can speak German.'], ['Wir müssen morgen arbeiten.', 'We must work tomorrow.'], ['Hier dürfen Sie nicht rauchen.', 'You are not allowed to smoke here.'], ['Was soll ich machen?', 'What should I do?']],
  [['können', 'can; to be able'], ['müssen', 'must; to have to'], ['dürfen', 'may; to be allowed'], ['wollen', 'to want'], ['sollen', 'should; to be supposed'], ['möchten', 'would like'], ['rauchen', 'to smoke'], ['erlaubt', 'allowed']],
  [fill('Du ___ hier nicht rauchen. (dürfen)', 'darfst', 'Use the du form of dürfen.'), choice('Which means you do not have to come?', ['Du darfst nicht kommen.', 'Du musst nicht kommen.', 'Du willst kommen.'], 1, 'nicht müssen removes an obligation.'), order('Say: We must work tomorrow.', 'Wir müssen morgen arbeiten', 'Modal second; infinitive last.'), listen('Der Kurs beginnt um neun Uhr. Sie müssen ein Heft mitbringen. Essen ist im Raum nicht erlaubt.', 'What must participants bring?', ['A notebook', 'Food', 'A computer'], 0), write('Write a short message saying what you can do and what you must do tomorrow.', 'Ich kann heute kommen. Morgen muss ich arbeiten. Am Abend möchte ich Deutsch lernen. Kannst du am Freitag kommen?')],
  ['Bibliothek: Bitte leise sprechen. Sie dürfen hier nicht essen. Bücher können Sie für drei Wochen ausleihen.', 'Which activity is prohibited?', ['Borrowing books', 'Eating', 'Speaking quietly'], 1, 'Look for nicht with dürfen.']);

lesson(18, 'Requests, instructions and object pronouns', 'Bitten und Hilfe',
  'Ask someone to do something and respond to their request. Practise formal and informal instructions, and replace familiar objects with pronouns.',
  ['Function', 'Example'], [['Formal instruction', 'Öffnen Sie bitte die Tür.'], ['Informal instruction', 'Mach bitte das Fenster zu.'], ['Group instruction', 'Kommt bitte um acht.'], ['Polite request', 'Könnten Sie mir bitte helfen?'], ['Object pronouns', 'mich, dich, ihn, sie, es, uns, euch'], ['Useful dative phrases', 'mir / dir / Ihnen helfen, danken']],
  ['Formal instructions use verb + Sie. Informal instructions have special short forms; learn frequent ones such as komm, nimm and gib.', 'A separable prefix still comes last in an instruction: Mach die Tür zu.', 'Replace a known object: der Schlüssel → ihn, die Tasche → sie, das Buch → es.', 'Learn helfen + mir/dir/Ihnen and Danke as useful everyday chunks.', 'Respond to requests: Ja, gern. Hier, bitte. Tut mir leid, das geht nicht.'],
  [['Geben Sie mir bitte den Schlüssel.', 'Please give me the key.'], ['Kannst du mich bitte anrufen?', 'Can you call me, please?'], ['Könnten Sie mir bitte helfen?', 'Could you help me, please?'], ['Ja, gern. Hier, bitte.', 'Yes, gladly. Here you are.']],
  [['helfen', 'to help'], ['geben', 'to give'], ['öffnen', 'to open'], ['schließen', 'to close'], ['der Schlüssel', 'key', 'Schlüssel'], ['die Tür', 'door', 'Türen'], ['gern', 'gladly'], ['leider', 'unfortunately']],
  [fill('Kannst du ___ bitte anrufen? (me)', 'mich', 'anrufen takes an accusative person.'), choice('Choose the formal instruction.', ['Öffnen Sie bitte die Tür.', 'Sie die Tür öffnen.', 'Öffnet du die Tür.'], 0, 'Verb + Sie makes a formal instruction.'), order('Ask for the key politely.', 'Geben Sie mir bitte den Schlüssel', 'A request can begin with the imperative verb.'), listen('Entschuldigung, können Sie bitte das Fenster schließen? Es ist kalt. Vielen Dank.', 'What is the request?', ['Open the door', 'Close the window', 'Call a friend'], 1), write('Write three requests: one with Sie, one with du and one asking for help.', 'Öffnen Sie bitte die Tür. Kannst du mich anrufen? Könnten Sie mir bitte helfen?')],
  ['Bitte bringen Sie Ihren Ausweis mit. Kommen Sie zehn Minuten vor Ihrem Termin. Bei Fragen helfen wir Ihnen gern.', 'What should visitors bring?', ['Their passport or identity document', 'A friend', 'Food'], 0, 'Ausweis is an identity document.']);

lesson(19, 'Places, directions and useful prepositions', 'Wege und Orte',
  'Ask where a place is and follow simple directions. Learn common place and travel phrases with their correct articles.',
  ['Meaning', 'Phrase'], [['Where?', 'im Park / am Bahnhof / in der Stadt'], ['Where to?', 'nach Berlin / zur Schule / zum Bahnhof'], ['Origin', 'aus Deutschland / von der Arbeit'], ['Transport', 'mit dem Bus / mit der Bahn'], ['Directions', 'geradeaus / links / rechts'], ['Basic dative forms', 'dem Mann / der Frau / dem Kind / den Leuten']],
  ['Learn common preposition phrases together with their case: mit dem Bus, zu der Schule → zur Schule.', 'nach is used with many city and country names without articles: nach Bonn, nach Spanien.', 'Location and destination can differ: in der Stadt versus in die Stadt. Start with useful examples before generalising.', 'Use Wo ist …? for a location and Wie komme ich …? for directions.', 'Ask someone to repeat a direction if you miss an important detail.'],
  [['Wie komme ich zum Bahnhof?', 'How do I get to the station?'], ['Gehen Sie geradeaus und dann links.', 'Go straight ahead and then left.'], ['Ich fahre mit dem Bus.', 'I travel by bus.'], ['Die Apotheke ist neben dem Supermarkt.', 'The pharmacy is next to the supermarket.']],
  [['geradeaus', 'straight ahead'], ['links', 'left'], ['rechts', 'right'], ['der Bahnhof', 'station', 'Bahnhöfe'], ['die Apotheke', 'pharmacy', 'Apotheken'], ['die Haltestelle', 'stop', 'Haltestellen'], ['neben', 'next to'], ['gegenüber', 'opposite']],
  [fill('Ich fahre mit ___ Bus.', 'dem', 'mit takes the dative; Bus is masculine.'), choice('You hear dann rechts. What should you do?', ['Turn right next', 'Turn left next', 'Stop immediately'], 0, 'rechts means right.', { englishOptions: true }), order('Ask how to get to the station.', 'Wie komme ich zum Bahnhof', 'Question word + verb + subject.'), listen('Die Bank ist nicht hier. Gehen Sie geradeaus und dann links. Die Bank ist neben der Post.', 'Where is the bank?', ['Next to the post office', 'Inside the station', 'Next to the school'], 0), write('Give three short directions to a place.', 'Gehen Sie geradeaus. Dann gehen Sie rechts. Die Apotheke ist neben dem Bahnhof.')],
  ['Neue Haltestelle: Der Bus hält ab Montag vor dem Bahnhof. Die alte Haltestelle am Markt ist geschlossen.', 'Where does the bus stop from Monday?', ['At the market', 'In front of the station', 'At the school'], 1, 'The notice announces a change of location.']);

lesson(20, 'Home, rooms and location', 'Wohnen',
  'Describe a home, locate everyday objects and understand a simple accommodation advertisement. Use frequent location phrases and es gibt.',
  ['Function', 'Example'], [['Existence', 'Es gibt einen Balkon.'], ['Rooms', 'die Küche, das Bad, das Schlafzimmer'], ['Location', 'auf dem Tisch / unter dem Bett'], ['Home', 'zu Hause / nach Hause'], ['Rent', 'Die Miete kostet 600 Euro.'], ['Description', 'Die Wohnung ist hell und ruhig.']],
  ['es gibt takes an accusative object: Es gibt einen Tisch.', 'Learn common location phrases as whole chunks: auf dem Tisch, in der Küche, unter dem Bett.', 'zu Hause describes being at home; nach Hause describes going home.', 'Predicate adjectives stay unchanged: Das Zimmer ist klein.', 'When reading advertisements check price, rooms, location and availability separately.'],
  [['Unsere Wohnung hat zwei Zimmer.', 'Our flat has two rooms.'], ['Der Schlüssel liegt auf dem Tisch.', 'The key is on the table.'], ['Es gibt einen Balkon.', 'There is a balcony.'], ['Ich gehe jetzt nach Hause.', 'I am going home now.']],
  [['die Miete', 'rent', 'Mieten'], ['das Zimmer', 'room', 'Zimmer'], ['die Küche', 'kitchen', 'Küchen'], ['das Bad', 'bathroom', 'Bäder'], ['der Balkon', 'balcony', 'Balkone'], ['hell', 'bright'], ['ruhig', 'quiet'], ['liegen', 'to lie; to be located']],
  [fill('Es gibt ___ Balkon.', 'einen', 'Es gibt takes the accusative.'), choice('Which means going home?', ['zu Hause', 'nach Hause', 'im Hause'], 1, 'Destination: nach Hause.'), order('Say where the key is.', 'Der Schlüssel liegt auf dem Tisch', 'Keep the verb second.'), listen('Die Wohnung hat drei Zimmer und einen Balkon. Die Miete ist siebenhundert Euro. Sie ist ab Juni frei.', 'How many rooms does the flat have?', ['Two', 'Three', 'Four'], 1), write('Describe your home or an invented home in four sentences.', 'Meine Wohnung hat zwei Zimmer. Die Küche ist klein. Es gibt einen Balkon. Die Wohnung ist ruhig.')],
  ['Zimmer frei: 18 Quadratmeter, 350 Euro im Monat. Küche und Bad sind gemeinsam. Frei ab 1. Mai. Kontakt per E-Mail.', 'What is shared?', ['Bedroom and balcony', 'Kitchen and bathroom', 'All furniture'], 1, 'gemeinsam means shared in this context.']);

lesson(21, 'Work, appointments and simple explanations', 'Arbeit und Termine',
  'Talk about your job, agree on an appointment and explain a cancellation. Connect short sentences using und, aber, oder, denn and dann.',
  ['Connector or phrase', 'Example'], [['und', 'Ich lerne und ich arbeite.'], ['aber', 'Ich habe Zeit, aber ich bin krank.'], ['oder', 'Montag oder Dienstag?'], ['denn', 'Ich komme nicht, denn ich muss arbeiten.'], ['dann', 'Ich esse. Dann gehe ich zur Arbeit.'], ['Time range', 'von acht bis sechzehn Uhr']],
  ['und, aber, oder and denn connect simple clauses without sending the verb to the end.', 'dann occupies the first position in a new clause: Dann gehe ich.', 'A short clear reason is enough at A1: Ich bin krank. Ich muss arbeiten.', 'Use Können wir …? to suggest an appointment and ask for confirmation.', 'Recognise berufliche contact words: Firma, Kollege, Termin, Besprechung.'],
  [['Ich arbeite als Verkäuferin.', 'I work as a shop assistant.'], ['Können wir den Termin ändern?', 'Can we change the appointment?'], ['Ich kann nicht kommen, denn ich muss arbeiten.', 'I cannot come because I have to work.'], ['Dann treffen wir uns am Dienstag.', 'Then we will meet on Tuesday.']],
  [['der Beruf', 'profession', 'Berufe'], ['die Firma', 'company', 'Firmen'], ['der Kollege', 'colleague', 'Kollegen'], ['die Kollegin', 'female colleague', 'Kolleginnen'], ['der Termin', 'appointment', 'Termine'], ['ändern', 'to change'], ['denn', 'because'], ['dann', 'then']],
  [fill('Ich komme nicht, ___ ich muss arbeiten. (because)', 'denn', 'denn joins two clauses with normal verb order.'), choice('Choose the correct word order.', ['Dann ich gehe zur Arbeit.', 'Dann gehe ich zur Arbeit.', 'Dann zur Arbeit ich gehe.'], 1, 'dann first; verb second.'), order('Ask to change an appointment.', 'Können wir den Termin ändern', 'The infinitive follows the object at the end.'), listen('Guten Tag, hier ist Frau Klein. Unser Termin ist nicht am Montag, sondern am Dienstag um elf Uhr. Bitte rufen Sie zurück.', 'When is the appointment?', ['Monday at eleven', 'Tuesday at eleven', 'Tuesday at one'], 1), write('Write about 30 words: cancel an appointment, give a reason, and suggest another day.', 'Guten Tag Frau Klein, leider kann ich am Montag nicht kommen. Ich muss arbeiten. Können wir uns am Dienstag um elf Uhr treffen? Vielen Dank. Viele Grüße, Lina')],
  ['Bürohilfe gesucht: Montag bis Freitag, 9–13 Uhr. Gute Deutschkenntnisse sind wichtig. Bitte schreiben Sie eine kurze E-Mail an unser Büro.', 'How should someone apply?', ['By email', 'Only by telephone', 'In person on Sunday'], 0, 'The advertisement specifies a short email.']);

lesson(22, 'Health, needs and asking for assistance', 'Gesundheit',
  'Say what hurts, arrange a basic appointment and ask for help. Learn useful dative phrases and instructions without trying to give medical advice.',
  ['Need', 'Phrase'], [['General condition', 'Mir geht es nicht gut.'], ['Pain', 'Mein Kopf tut weh.'], ['Appointment', 'Ich brauche einen Termin.'], ['Help', 'Können Sie mir helfen?'], ['Instruction', 'Sie sollen viel Wasser trinken.'], ['Urgency', 'Ich brauche Hilfe.']],
  ['Use familiar body words with a simple pain phrase: Mein Bauch tut weh.', 'Learn Mir geht es … as a whole expression. Do not replace mir with ich.', 'Remember helfen + dative: mir, dir, Ihnen.', 'Use müssen for your own need and sollen for an instruction received.', 'Describe symptoms and practical needs; a language exercise does not diagnose illness.'],
  [['Mein Hals tut weh.', 'My throat hurts.'], ['Ich möchte einen Termin beim Arzt.', 'I would like a doctor’s appointment.'], ['Mir geht es heute besser.', 'I feel better today.'], ['Können Sie mir bitte helfen?', 'Can you help me, please?']],
  [['der Kopf', 'head', 'Köpfe'], ['der Hals', 'throat; neck', 'Hälse'], ['der Bauch', 'belly', 'Bäuche'], ['krank', 'ill'], ['der Arzt', 'doctor', 'Ärzte'], ['die Ärztin', 'female doctor', 'Ärztinnen'], ['die Praxis', 'medical practice', 'Praxen'], ['wehtun', 'to hurt']],
  [fill('___ geht es nicht gut. (to me)', 'Mir', 'The expression uses a dative pronoun.'), choice('Choose the correct phrase.', ['Sie helfen ich.', 'Sie helfen mir.', 'Sie helfen mich.'], 1, 'helfen takes a dative person.'), order('Ask for an appointment.', 'Ich brauche einen Termin', 'Termin is a masculine object.'), listen('Die Praxis ist heute bis zwölf Uhr geöffnet. Frau Dr. Wolf ist morgen wieder da. Für einen Termin rufen Sie bitte am Morgen an.', 'When should you phone for an appointment?', ['In the morning', 'At night', 'Only after twelve'], 0), write('Write a short message to cancel a class: say you are ill, cannot come, and ask about homework.', 'Guten Tag, ich bin heute krank und kann nicht zum Kurs kommen. Welche Hausaufgaben soll ich machen? Vielen Dank für Ihre Hilfe. Viele Grüße, Amir')],
  ['Praxis Dr. Wolf: Montag bis Freitag 8–12 Uhr. Mittwoch auch 15–18 Uhr. Termine nur nach telefonischer Anmeldung.', 'How do patients arrange a visit?', ['By telephone', 'By postcard only', 'No appointment is needed'], 0, 'telefonische Anmeldung means registration by telephone.']);

lesson(23, 'Travel, tickets and accommodation', 'Unterwegs',
  'Buy a ticket, understand station information and ask about accommodation. Practise destinations, return journeys and travel dates.',
  ['Function', 'Phrase'], [['Ticket', 'Eine Fahrkarte nach Bonn, bitte.'], ['Return', 'Hin und zurück.'], ['Destination', 'nach Berlin / in die Schweiz'], ['Accommodation', 'ein Einzelzimmer / ein Doppelzimmer'], ['Dates', 'von Freitag bis Sonntag'], ['Arrival', 'Wann kommt der Zug an?']],
  ['Check destination, platform, departure time and delay as separate listening details.', 'nach goes with many place names without an article; learn country article phrases individually.', 'For a hotel enquiry use Ich möchte … reservieren and ask Was kostet …?', 'Separable travel verbs include abfahren, ankommen and umsteigen.', 'Learn useful travel chunks: hin und zurück, nur hin, mit dem Zug.'],
  [['Ich möchte ein Doppelzimmer reservieren.', 'I would like to reserve a double room.'], ['Der Zug kommt um zehn Uhr an.', 'The train arrives at ten.'], ['Muss ich in Köln umsteigen?', 'Do I have to change trains in Cologne?'], ['Eine Fahrkarte hin und zurück, bitte.', 'A return ticket, please.']],
  [['die Fahrkarte', 'ticket', 'Fahrkarten'], ['das Gleis', 'platform track', 'Gleise'], ['umsteigen', 'to change trains'], ['ankommen', 'to arrive'], ['reservieren', 'to reserve'], ['das Einzelzimmer', 'single room', 'Einzelzimmer'], ['das Doppelzimmer', 'double room', 'Doppelzimmer'], ['die Verspätung', 'delay', 'Verspätungen']],
  [fill('Wann kommt der Zug ___? (ankommen)', 'an', 'The separable prefix goes at the end.'), choice('What does hin und zurück mean?', ['One way', 'Return journey', 'Platform change'], 1, 'It means there and back.', { englishOptions: true }), order('Ask about changing trains.', 'Muss ich in Köln umsteigen', 'The modal starts the question; infinitive ends it.'), listen('Der Zug nach Bonn fährt heute von Gleis fünf. Die Abfahrt ist um vierzehn Uhr zehn, nicht um vierzehn Uhr.', 'Which platform track is used?', ['Four', 'Five', 'Ten'], 1), write('Write about 30 words to a hotel: give dates, request a double room, and ask the price.', 'Guten Tag, wir möchten von Freitag bis Sonntag in Bonn bleiben. Haben Sie ein Doppelzimmer für zwei Personen? Was kostet das Zimmer mit Frühstück? Vielen Dank. Viele Grüße, Anna')],
  ['Hotel Linden: Einzelzimmer ab 55 Euro, Doppelzimmer ab 80 Euro. Frühstück kostet 9 Euro pro Person. Hunde sind nicht erlaubt.', 'Is breakfast included in the stated room prices?', ['Yes', 'No, it costs extra', 'Only for dogs'], 1, 'A separate breakfast price means an additional charge.']);

lesson(24, 'Weather, clothes and simple descriptions', 'Wetter und Kleidung',
  'Understand a basic forecast, describe what you need and compare simple choices. Practise es as the subject of weather expressions.',
  ['Expression', 'Meaning'], [['Es regnet / Es schneit.', 'It rains / It snows.'], ['Es ist warm / kalt.', 'It is warm / cold.'], ['Die Sonne scheint.', 'The sun is shining.'], ['im Frühling / im Winter', 'in spring / in winter'], ['besser / lieber', 'better / preferably'], ['größer / kleiner', 'bigger / smaller']],
  ['Many weather expressions use es: Es regnet. Es ist kalt.', 'Use im with seasons: im Winter.', 'Predicate adjectives are unchanged: Die Schuhe sind klein.', 'Learn frequent comparisons as useful words: gut → besser, gern → lieber.', 'Recognise clothing words in shops and pack what a weather notice suggests.'],
  [['Heute ist es kalt und es regnet.', 'Today it is cold and it is raining.'], ['Ich brauche eine Jacke.', 'I need a jacket.'], ['Diese Schuhe sind zu klein.', 'These shoes are too small.'], ['Ich trinke lieber Tee.', 'I prefer drinking tea.']],
  [['regnen', 'to rain'], ['schneien', 'to snow'], ['der Regen', 'rain', '-'], ['die Sonne', 'sun', '-'], ['der Winter', 'winter', 'Winter'], ['der Sommer', 'summer', 'Sommer'], ['der Schuh', 'shoe', 'Schuhe'], ['warm', 'warm']],
  [fill('Im Winter ___ es oft. (schneien)', 'schneit', 'Weather uses the singular es form.'), choice('Choose the comparison for gut.', ['guter', 'besser', 'gutest'], 1, 'Learn gut → besser as a useful pair.'), order('Say that you need a jacket.', 'Ich brauche eine Jacke', 'Jacke is a feminine object.'), listen('Am Samstag ist es warm und sonnig. Am Sonntag regnet es, und es ist kalt.', 'What is the weather like on Sunday?', ['Warm and sunny', 'Cold and rainy', 'Hot and dry'], 1), write('Write four sentences about the weather and what you wear or need.', 'Heute ist es kalt. Es regnet. Ich brauche eine Jacke und Schuhe. Im Sommer trage ich gern ein T-Shirt.')],
  ['Ausflug am Sonntag: Bitte bringen Sie eine Jacke mit. Es regnet am Nachmittag. Wir treffen uns um 9 Uhr am Bahnhof.', 'What should participants bring?', ['A jacket', 'A bicycle', 'An umbrella only'], 0, 'Answer from the notice, not from what you might personally pack.']);

lesson(25, 'Hobbies, invitations and arrangements', 'Freizeit und Freunde',
  'Talk about free time, invite someone and respond. Use short explanations, clear questions and a suitable greeting and ending in messages.',
  ['Function', 'Phrase'], [['Hobby', 'Ich spiele gern Fußball.'], ['Invite', 'Möchtest du mitkommen?'], ['Accept', 'Ja, gern.'], ['Decline', 'Leider habe ich keine Zeit.'], ['Suggest', 'Treffen wir uns am Samstag?'], ['Arrange', 'Um drei vor dem Kino.']],
  ['Use gern after the conjugated verb to say you enjoy an activity.', 'A suggestion may be a verb-first question: Treffen wir uns morgen?', 'An invitation needs a place and time; a reply should accept or decline clearly.', 'Give a simple reason with a separate sentence or denn.', 'Use a friendly greeting and ending: Hallo … / Viele Grüße …'],
  [['Ich höre gern Musik.', 'I enjoy listening to music.'], ['Möchtest du am Samstag mitkommen?', 'Would you like to come along on Saturday?'], ['Leider kann ich nicht kommen.', 'Unfortunately I cannot come.'], ['Treffen wir uns vor dem Kino?', 'Shall we meet in front of the cinema?']],
  [['die Einladung', 'invitation', 'Einladungen'], ['das Kino', 'cinema', 'Kinos'], ['die Musik', 'music', '-'], ['mitkommen', 'to come along'], ['sich treffen', 'to meet each other'], ['tanzen', 'to dance'], ['schwimmen', 'to swim'], ['spazieren gehen', 'to go for a walk']],
  [fill('Ich spiele ___ Fußball. (gladly)', 'gern', 'gern expresses enjoyment.'), choice('Which response clearly declines an invitation?', ['Ja, gern.', 'Leider kann ich nicht kommen.', 'Bis Samstag!'], 1, 'The reply says the person cannot attend.'), order('Invite someone to come along.', 'Möchtest du am Samstag mitkommen', 'The infinitive with its prefix stays together.'), listen('Hallo Lea, am Samstag gehen wir ins Kino. Der Film beginnt um acht, aber wir treffen uns um halb acht vor dem Kino.', 'When is the meeting?', ['19:30', '20:00', '20:30'], 0), write('Write about 30 words inviting a friend: say what you plan, give time and place, and ask for a reply.', 'Hallo Tim, möchtest du am Samstag mit ins Kino kommen? Wir treffen uns um halb acht vor dem Kino. Hast du Zeit? Schreib mir bitte. Viele Grüße, Lea')],
  ['Hallo Sam, ich kann heute nicht schwimmen gehen. Ich muss bis 18 Uhr arbeiten. Hast du morgen Zeit? Dann können wir ins Schwimmbad gehen. Grüße, Alex', 'What does Alex suggest?', ['Swimming today', 'Swimming tomorrow', 'Working together tomorrow'], 1, 'The proposed new day follows the cancellation.']);

lesson(26, 'Talking about completed actions with haben', 'Perfekt mit haben',
  'Recognise and use a small set of useful past actions. The goal is to understand everyday messages and give a short account of yesterday.',
  ['Infinitive', 'Past expression'], [['machen', 'ich habe gemacht'], ['lernen', 'ich habe gelernt'], ['arbeiten', 'ich habe gearbeitet'], ['kaufen / einkaufen', 'ich habe gekauft / eingekauft'], ['essen / trinken', 'ich habe gegessen / getrunken'], ['lesen / sehen', 'ich habe gelesen / gesehen']],
  ['The Perfekt often uses a form of haben plus a past participle at the end.', 'Learn the participle with the verb. Some are regular, many common ones are irregular.', 'A separable verb puts ge between prefix and stem: einkaufen → eingekauft.', 'Verbs ending in -ieren do not add ge: telefonieren → telefoniert.', 'Ask about past actions: Was hast du gestern gemacht?'],
  [['Ich habe gestern Deutsch gelernt.', 'I studied German yesterday.'], ['Wir haben Brot gekauft.', 'We bought bread.'], ['Hast du schon gegessen?', 'Have you already eaten?'], ['Sie hat mit ihrer Mutter telefoniert.', 'She spoke with her mother on the phone.']],
  [['gestern', 'yesterday'], ['schon', 'already'], ['machen', 'to do; to make'], ['lernen', 'to learn'], ['essen', 'to eat'], ['trinken', 'to drink'], ['telefonieren', 'to telephone'], ['die Hausaufgabe', 'homework task', 'Hausaufgaben']],
  [fill('Ich habe Deutsch ___. (lernen)', 'gelernt', 'Regular participle: ge + stem + t.'), choice('Choose the participle of essen.', ['geesst', 'gegessen', 'essiert'], 1, 'Learn essen → gegessen.'), order('Say what you bought yesterday.', 'Ich habe gestern Brot gekauft', 'haben second; participle last.'), listen('Gestern habe ich gearbeitet. Am Abend habe ich gekocht und einen Film gesehen. Heute habe ich frei.', 'What did the speaker do in the evening?', ['Worked at a station', 'Cooked and watched a film', 'Bought a car'], 1), write('Write four short sentences about yesterday using haben.', 'Ich habe gestern gearbeitet. Ich habe Deutsch gelernt. Am Abend habe ich gekocht. Danach habe ich einen Film gesehen.')],
  ['Hallo Mia, ich habe die Fahrkarten gekauft. Der Zug fährt morgen um 8 Uhr. Hast du das Hotel reserviert? Grüße, Ben', 'What has Ben already done?', ['Bought the tickets', 'Reserved the hotel', 'Taken the train'], 0, 'Separate a completed action from tomorrow’s plan.']);

lesson(27, 'Travel and completed actions with sein', 'Perfekt mit sein',
  'Understand a short account of a journey and learn the auxiliary with common verbs. Use a limited set of familiar past forms accurately.',
  ['Verb', 'Past expression'], [['gehen', 'ich bin gegangen'], ['kommen', 'ich bin gekommen'], ['fahren', 'ich bin gefahren'], ['bleiben', 'ich bin geblieben'], ['aufstehen', 'ich bin aufgestanden'], ['sein', 'ich bin gewesen']],
  ['Several common movement and change verbs use sein in the Perfekt; learn each useful verb with its auxiliary.', 'bleiben and sein also use sein, although they do not describe movement.', 'Keep the auxiliary conjugated and the participle at the end.', 'Use an exact destination phrase: nach Berlin, zum Bahnhof, nach Hause.', 'Avoid treating every verb as regular. Learn gefahren, gekommen and gegangen as units.'],
  [['Ich bin gestern nach Hamburg gefahren.', 'I travelled to Hamburg yesterday.'], ['Wir sind zu Hause geblieben.', 'We stayed at home.'], ['Wann bist du angekommen?', 'When did you arrive?'], ['Er ist um sieben Uhr aufgestanden.', 'He got up at seven.']],
  [['gehen', 'to go'], ['kommen', 'to come'], ['fahren', 'to travel; to drive'], ['bleiben', 'to stay'], ['aufstehen', 'to get up'], ['zurückkommen', 'to come back'], ['die Reise', 'journey', 'Reisen'], ['ankommen', 'to arrive']],
  [fill('Wir ___ nach Bonn gefahren.', 'sind', 'fahren uses sein for this journey.'), choice('Choose the correct past expression.', ['Ich habe geblieben.', 'Ich bin geblieben.', 'Ich bin gebleibt.'], 1, 'bleiben → ist geblieben.'), order('Say when you got up.', 'Ich bin um sieben Uhr aufgestanden', 'The participle finishes the sentence.'), listen('Am Freitag bin ich nach Bonn gefahren. Ich bin zwei Tage geblieben und am Sonntag zurückgekommen.', 'When did the speaker return?', ['Friday', 'Saturday', 'Sunday'], 2), write('Write four simple sentences about an invented journey.', 'Ich bin nach Bonn gefahren. Ich bin zwei Tage geblieben. Am Samstag bin ich ins Museum gegangen. Am Sonntag bin ich zurückgekommen.')],
  ['Liebe Eva, wir sind gestern in Berlin angekommen. Das Hotel ist schön. Heute besuchen wir ein Museum. Am Freitag fahren wir nach Hause. Grüße, Tom', 'When did they arrive?', ['Yesterday', 'Today', 'Friday'], 0, 'angekommen describes the completed arrival.']);

lesson(28, 'Simple past descriptions: war and hatte', 'War und hatte',
  'Use two common past verbs to give a short reason or describe a previous situation. Keep your explanation simple and understandable.',
  ['Subject', 'sein in the past', 'haben in the past'], [['ich', 'war', 'hatte'], ['du', 'warst', 'hattest'], ['er / sie / es', 'war', 'hatte'], ['wir', 'waren', 'hatten'], ['ihr', 'wart', 'hattet'], ['sie / Sie', 'waren', 'hatten']],
  ['Use war for a past state or location: Ich war krank. Ich war in Bonn.', 'Use hatte for possession, time or an appointment in the past: Ich hatte keine Zeit.', 'The verb still takes position two in a statement.', 'A short explanation often needs only one clause. Do not add grammar you cannot control.', 'Recognise gestern, letzte Woche and am Montag as signals of time.'],
  [['Ich war gestern krank.', 'I was ill yesterday.'], ['Wir hatten keine Zeit.', 'We had no time.'], ['Der Kurs war gut.', 'The course was good.'], ['Am Montag hatte ich einen Termin.', 'On Monday I had an appointment.']],
  [['letzte Woche', 'last week'], ['krank', 'ill'], ['der Termin', 'appointment', 'Termine'], ['die Zeit', 'time', '-'], ['müde', 'tired'], ['gut', 'good'], ['schlecht', 'bad'], ['da', 'there']],
  [fill('Ich ___ gestern krank. (sein)', 'war', 'A past state uses war.'), choice('Choose the correct sentence.', ['Wir hatte keine Zeit.', 'Wir hatten keine Zeit.', 'Wir war keine Zeit.'], 1, 'wir → hatten.'), order('Begin with the time: Yesterday I was at home.', 'Gestern war ich zu Hause', 'Time first; past verb second.'), listen('Entschuldigung, ich war gestern nicht im Kurs. Ich war krank und hatte einen Termin beim Arzt.', 'Why was the speaker absent?', ['Illness and a doctor’s appointment', 'A holiday', 'A shopping trip'], 0), write('Write a short apology: say where you were, give a reason, and ask about the next class.', 'Guten Tag, gestern war ich nicht im Kurs. Ich war krank und hatte einen Termin beim Arzt. Wann ist der nächste Unterricht? Viele Grüße, Nora')],
  ['Hallo Paul, die Party war sehr schön. Leider warst du nicht da. Hattest du keine Zeit? Wir treffen uns nächste Woche wieder. Grüße, Sara', 'Was Paul at the party?', ['Yes', 'No', 'The message does not say'], 1, 'Leider warst du nicht da makes the absence clear.']);

lesson(29, 'Reading messages, advertisements and signs', 'Lesen im Alltag',
  'Read for a practical purpose. Find who, when, where and what, then check the full meaning rather than matching an isolated word.',
  ['Text', 'Reading action'], [['Short message', 'Identify the sender, purpose and arrangement.'], ['Advertisement', 'Compare the stated need with the offer.'], ['Sign or notice', 'Check what is permitted, prohibited or changed.'], ['True / false', 'Test the whole statement against the text.'], ['Distractor', 'Check time, place and negation carefully.']],
  ['Read the question first so you know what detail matters.', 'Circle dates, prices and opening hours mentally, then read the words around them.', 'A word appearing in both question and text does not prove the answer.', 'Beware of nicht, kein, nur, ab and geschlossen.', 'When choosing an advertisement, compare every important condition, including the time and place.'],
  [['Nur für Mitarbeiter.', 'For staff only.'], ['Heute geschlossen.', 'Closed today.'], ['Geöffnet ab zehn Uhr.', 'Open from ten o’clock.'], ['Bitte den anderen Eingang benutzen.', 'Please use the other entrance.']],
  [['geschlossen', 'closed'], ['geöffnet', 'open'], ['der Eingang', 'entrance', 'Eingänge'], ['der Ausgang', 'exit', 'Ausgänge'], ['nur', 'only'], ['ab', 'from; starting at'], ['die Anzeige', 'advertisement', 'Anzeigen'], ['benutzen', 'to use']],
  [choice('Notice: Eintritt nur mit Fahrkarte. Who may enter?', ['Anyone', 'People with a ticket', 'Only drivers'], 1, 'nur mit makes the ticket a condition.', { englishOptions: true }), fill('Heute ___: Der Laden ist nicht offen.', 'geschlossen', 'Recognise the sign as a complete message.'), order('Form a simple instruction.', 'Bitte benutzen Sie den Eingang links', 'A polite formal instruction uses verb + Sie.'), listen('Die Bibliothek ist heute geschlossen. Morgen öffnen wir wieder um neun Uhr.', 'When will the library open again?', ['Today at nine', 'Tomorrow at nine', 'Tomorrow at ten'], 1), write('Write two short signs: one says closed today, one asks visitors to use another entrance.', 'Heute geschlossen. Bitte benutzen Sie den Eingang rechts.')],
  ['A: Zimmer im Zentrum, 420 Euro, frei ab Juni. B: Zimmer am Bahnhof, 380 Euro, frei ab April. Sie suchen ein Zimmer ab April für höchstens 400 Euro.', 'Which advertisement fits the stated need?', ['A', 'B', 'Neither'], 1, 'Both starting date and budget must match.']);

lesson(30, 'Listening for key details and corrections', 'Hören im Alltag',
  'Listen to dialogues, announcements and phone messages. Practise finding a requested detail under time pressure, including information that is corrected later.',
  ['Task', 'Strategy'], [['Dialogue', 'Know which person or detail the question asks about.'], ['Announcement', 'Listen for place, time, change and negation.'], ['Phone message', 'Identify the reason for the call and requested action.'], ['Correction', 'Use the final information after aber / nicht … sondern.'], ['Numbers', 'Distinguish -zehn, -zig and half-hour expressions.']],
  ['Read options before starting the audio when the task allows it.', 'A speaker may mention a wrong time before correcting it. Follow the whole message.', 'Listen once for purpose, then again for the requested detail in training. Practise the official playback limits before the exam.', 'Train with unfamiliar voices and the official recordings, as well as the app voice.', 'Do not open the transcript until you have made an independent attempt.'],
  [['Der Termin ist nicht um zehn, sondern um elf Uhr.', 'The appointment is not at ten but at eleven.'], ['Bitte rufen Sie zurück.', 'Please call back.'], ['Der Zug hat zehn Minuten Verspätung.', 'The train is ten minutes late.'], ['Wir treffen uns um halb neun.', 'We meet at eight thirty.']],
  [['die Nachricht', 'message', 'Nachrichten'], ['zurückrufen', 'to call back'], ['die Durchsage', 'announcement', 'Durchsagen'], ['die Abfahrt', 'departure', 'Abfahrten'], ['die Ankunft', 'arrival', 'Ankünfte'], ['sondern', 'but instead'], ['später', 'later'], ['früher', 'earlier']],
  [listen('Hallo Kim, unser Termin ist nicht um neun. Ich kann erst um zehn kommen. Treffen wir uns vor dem Café?', 'When is the proposed meeting?', ['9:00', '10:00', '11:00'], 1), listen('Achtung: Der Zug nach Essen fährt heute nicht von Gleis zwei, sondern von Gleis vier.', 'Which platform track is used today?', ['Two', 'Four', 'Essen'], 1), fill('Halb neun bedeutet ___ Uhr dreißig. (write the number as a word)', 'acht', 'halb points toward the next hour.'), order('Ask someone to call back.', 'Rufen Sie bitte zurück', 'The separated prefix comes last.'), write('Write a short phone message: change a time and ask the listener to call back.', 'Guten Tag, unser Termin ist nicht um neun, sondern um zehn Uhr. Bitte rufen Sie zurück. Vielen Dank.')],
  ['Training: Hören Sie zuerst ohne Text. Wählen Sie eine Antwort. Lesen Sie dann die Nachricht und prüfen Sie den wichtigen Satz.', 'What comes before reading the transcript?', ['Listening and choosing an answer', 'Memorising every word', 'Writing the transcript'], 0, 'Make an independent listening attempt first.']);

lesson(31, 'Forms and short everyday messages', 'Schreiben im Alltag',
  'Write a clear short message and complete a form from a supplied profile. Build a message around its three requested content points.',
  ['Message part', 'Useful expression'], [['Friendly greeting', 'Hallo … / Liebe … / Lieber …'], ['Formal greeting', 'Guten Tag … / Sehr geehrte Frau …'], ['Purpose', 'Ich möchte … / Ich schreibe …'], ['Reason or information', 'Ich kann nicht kommen. Ich muss arbeiten.'], ['Question', 'Wann haben Sie Zeit?'], ['Ending', 'Viele Grüße / Mit freundlichen Grüßen']],
  ['Read all content points and write a sentence for each one. Add an appropriate greeting and ending.', 'A short message of about 30 words is the usual model task. Communicating all requested information matters more than decorative complexity.', 'For a form, use the supplied profile and keep numbers and spellings exact.', 'Choose du or Sie consistently according to the recipient.', 'After writing, check verb position, noun capitals and whether every requested point is answered.'],
  [['Ich möchte einen Termin vereinbaren.', 'I would like to arrange an appointment.'], ['Leider kann ich am Freitag nicht kommen.', 'Unfortunately I cannot come on Friday.'], ['Können wir uns am Montag treffen?', 'Can we meet on Monday?'], ['Vielen Dank für Ihre Hilfe.', 'Thank you for your help.']],
  [['das Formular', 'form', 'Formulare'], ['die Anmeldung', 'registration', 'Anmeldungen'], ['vereinbaren', 'to arrange'], ['der Betreff', 'subject line', 'Betreffe'], ['die Antwort', 'answer; reply', 'Antworten'], ['schreiben', 'to write'], ['freundlich', 'friendly'], ['die Information', 'information', 'Informationen']],
  [choice('A task has three content points. What should your message do?', ['Answer all three clearly', 'Only give a long greeting', 'Use the most advanced grammar possible'], 0, 'Cover the requested information.', { englishOptions: true }), fill('Mit freundlichen ___.', 'Grüßen', 'A standard formal ending.'), order('Ask to meet on Monday.', 'Können wir uns am Montag treffen', 'Keep the infinitive at the end.'), listen('Ich heiße Sara Wolf. Meine Tochter heißt Mia. Für den Kurs möchte ich meine Tochter anmelden, nicht mich.', 'Whose name goes on the participant form?', ['Sara Wolf', 'Mia Wolf', 'Both automatically'], 1), write('Write about 30 words to a language school: ask about a beginner course, ask when it starts, and ask its price.', 'Guten Tag, ich möchte einen Deutschkurs für Anfänger machen. Wann beginnt der nächste Kurs? Wie viel kostet er? Bitte schicken Sie mir Informationen. Vielen Dank. Mit freundlichen Grüßen, Lina')],
  ['Profil: Ben Walter, geboren am 8. April 1999 in Kiel, wohnt in Bremen. Er möchte einen Kurs am Abend machen.', 'What goes in the Wohnort field?', ['Kiel', 'Bremen', '8 April 1999'], 1, 'Wohnort is the present town of residence.']);

lesson(32, 'Speaking: introduction, questions and requests', 'Sprechen im Alltag',
  'Complete a full speaking rehearsal with a partner. Introduce yourself, spell and give a number, then exchange information and make requests with suitable responses.',
  ['Round', 'What to do'], [['Introduction', 'Name, age, origin, home, languages, work and hobby.'], ['Follow-up', 'Spell a name or place; say a number.'], ['Information exchange', 'Ask one relevant question and answer your partner.'], ['Request', 'Ask for an object or an action.'], ['Response', 'Accept, refuse politely or offer help.'], ['Repair', 'Ask for repetition when needed.']],
  ['Speak from keywords rather than reciting one memorised paragraph for every task.', 'A question must match the topic and card: Essen + Frühstück → Was isst du zum Frühstück?', 'A request needs a suitable response. Practise both roles.', 'Aim for understandable speech and task completion. A perfect accent is unnecessary.', 'Use a partner or tutor to review the exchange; the app does not award an official speaking mark.'],
  [['Ich heiße Amir und bin 25 Jahre alt.', 'My name is Amir and I am 25 years old.'], ['Was machst du am Wochenende?', 'What do you do at the weekend?'], ['Können Sie mir bitte einen Stift geben?', 'Can you give me a pen, please?'], ['Ja, gern. Hier ist ein Stift.', 'Yes, gladly. Here is a pen.']],
  [['sich vorstellen', 'to introduce oneself'], ['die Frage', 'question', 'Fragen'], ['antworten', 'to answer'], ['bitten', 'to request'], ['der Stift', 'pen', 'Stifte'], ['der Partner', 'partner', 'Partner'], ['noch einmal', 'once again'], ['natürlich', 'of course']],
  [choice('Topic: Essen. Card: Frühstück. Which question fits?', ['Was isst du zum Frühstück?', 'Wo ist der Bahnhof?', 'Wie viel kostet dein Zimmer?'], 0, 'Match both the topic and the card.'), fill('Können Sie das bitte ___? (repeat)', 'wiederholen', 'Use a repair phrase when needed.'), order('Ask for a pen politely.', 'Können Sie mir bitte einen Stift geben', 'Modal first, infinitive last.'), listen('Ich heiße Ana, komme aus Portugal und wohne in Dresden. Ich bin Verkäuferin und höre gern Musik.', 'Where does Ana live?', ['Portugal', 'Dresden', 'Berlin'], 1), write('Prepare keywords for your introduction and write one question and one request. Then speak without reading the sentences.', 'Name: Amir. Alter: 25. Land: Indien. Wohnort: Bonn. Beruf: Student. Hobby: Fußball. Was machst du am Samstag? Können Sie mir bitte einen Stift geben?')],
  ['Partnertraining: Person A zieht eine Karte und fragt. Person B antwortet und stellt dann eine neue Frage. Beide machen danach eine Bitte und reagieren auf die Bitte des Partners.', 'Who practises questions and responses?', ['Only person A', 'Only person B', 'Both people'], 2, 'Both roles are part of the exchange.']);

const module = (id, title, lessonIds, topics, goals, pronunciation, listening, reading, writing, speaking, checkpoint) => ({ id, title, lessonIds, topics, goals, pronunciation, listening, reading, writing, speaking, checkpoint, hours: 8 });
const modules = [
  module(1, 'First sounds and first conversations', [9,1], ['alphabet','hello'], ['Greet and introduce yourself using du and Sie.', 'Spell your name and ask for repetition.'], 'ei / ie, sch, ich / ach, umlauts and word stress. Practise the alphabet aloud.', 'Listen to three short introductions; note the names and origins.', 'Read simple greetings and contact cards.', 'Write a four-sentence personal introduction.', 'Introduce yourself; spell a surname; respond to Woher kommen Sie?', 'Give an understandable 45-second introduction and spell a supplied name without reading a sentence.'),
  module(2, 'Numbers and personal information', [10,11], ['numbers','post'], ['Understand prices, ages and contact numbers.', 'Transfer someone else’s profile accurately to a form.'], 'Contrast dreizehn / dreißig and sechzehn / sechzig. Read numbers slowly, then naturally.', 'Take down five telephone numbers and recognise corrected numbers.', 'Read personal profiles and registration fields.', 'Fill five form fields from an invented profile.', 'Give an age, postcode and phone number; ask for contact details.', 'Complete five profile fields accurately and understand four of five spoken number details.'),
  module(3, 'Actions and useful questions', [2,13], ['verbs','class'], ['Describe familiar actions in the present tense.', 'Ask and answer W-questions and yes/no questions.'], 'Final consonants and verb endings -e, -st, -t, -en. Speak a question with natural stress.', 'Find who is doing an action and when.', 'Read a short classroom timetable.', 'Write four questions for a new classmate.', 'Exchange questions about home, language and daily actions.', 'Produce four relevant questions with the right question word and answer them independently.'),
  module(4, 'People, nouns and possession', [3,12], ['family','animals','things'], ['Use articles and common plurals with familiar nouns.', 'Describe family members and identify possessions.'], 'Practise noun stress and distinguish singular / plural forms in speech.', 'Listen to a family description and draw a simple family tree.', 'Read a short family profile.', 'Write four sentences about two people.', 'Describe two family members and answer a question about each.', 'Retrieve ten nouns with their articles and describe a family without relying on a full script.'),
  module(5, 'Word order, time and appointments', [4,7], ['time','little'], ['Keep the finite verb in the correct sentence position.', 'Understand digital time, informal time and appointment dates.'], 'Sentence stress; contrast halb acht / acht Uhr and quarter-hour expressions.', 'Identify five appointment times, including a corrected time.', 'Read opening hours and appointment cards.', 'Write a short appointment confirmation.', 'Ask for a time and repeat it back for confirmation.', 'Interpret four of five time expressions and confirm a date and place accurately.'),
  module(6, 'Routines and separable verbs', [14,8], ['verbs2','time'], ['Describe a weekday and weekend routine.', 'Use common separable verbs and frequency expressions.'], 'Stress the separable prefix: AUFstehen, EINkaufen, ANrufen. Link words in short groups.', 'Follow a daily routine and identify the order of activities.', 'Read a weekly schedule.', 'Write a six-sentence routine with at least two time phrases.', 'Describe your day and answer a follow-up question.', 'Explain a routine clearly using time, a frequency word and two separable verbs.'),
  module(7, 'Food, quantities and the accusative', [5,15], ['food','kitchen'], ['Order food and ask for a quantity.', 'Use frequent accusative objects and polite ordering phrases.'], 'Long / short vowels in everyday food words; use polite request intonation.', 'Understand an order and its total price.', 'Read a menu and a supermarket offer.', 'Write a short shopping list and a polite order.', 'Role-play customer and server, including paying.', 'Order two items, understand an alternative and ask to pay without a script.'),
  module(8, 'Negation and shopping', [6,16], ['people','describe'], ['Choose nicht or kein in familiar contexts.', 'Ask about price, size, colour and payment.'], 'Make negation audible; contrast fünfzehn / fünfzig in prices.', 'Identify item, price and whether it is available.', 'Choose an advertisement that meets two stated needs.', 'Write three shopping enquiries.', 'Role-play buying an item and politely declining an unsuitable option.', 'Select a suitable offer and explain a simple problem such as zu groß or zu teuer.'),
  module(9, 'Abilities, obligations and requests', [17,18], ['class','little'], ['Use modal verbs to express ability, need and permission.', 'Make and respond to requests; use useful object pronouns.'], 'Stress the important action and practise sentence brackets without long pauses.', 'Recognise instructions and prohibitions.', 'Read classroom and public rules.', 'Write three clear requests and a short instruction.', 'Take turns asking for an object, an action and help.', 'Make two different requests, respond suitably and distinguish prohibition from lack of obligation.'),
  module(10, 'Directions and housing', [19,20], ['town','places','home'], ['Follow directions and describe a location.', 'Understand a housing offer and use common dative phrases.'], 'Practise dem / den clearly; group prepositions with their noun phrases.', 'Follow a route and identify a flat’s rooms, price and availability.', 'Compare two accommodation advertisements.', 'Write a short enquiry about a room.', 'Ask for directions and describe where an object is.', 'Match a housing need to an offer and give or follow three simple directions.'),
  module(11, 'Work, appointments and health', [21,22], ['work','health'], ['Describe work and arrange or change an appointment.', 'Express a basic health need and ask for help.'], 'Practise clear reasons in short clauses; keep word endings audible.', 'Understand a changed appointment and a practice’s opening hours.', 'Read an appointment notice and job advertisement.', 'Write a cancellation covering the reason and a new proposal.', 'Role-play making an appointment and asking for assistance.', 'Handle an appointment change and write a complete three-point cancellation.'),
  module(12, 'Travel, weather and everyday choices', [23,24], ['travel','weather'], ['Buy a ticket, enquire about a room and understand travel details.', 'Understand a simple forecast and describe practical needs.'], 'Practise platform numbers, destination names and compound-word stress.', 'Identify a platform change, departure time and forecast detail.', 'Read travel notices and hotel advertisements.', 'Write a three-point hotel enquiry.', 'Role-play buying a ticket and asking about a hotel room.', 'Explain a travel request, identify a changed detail and ask a relevant follow-up question.'),
  module(13, 'Friends, invitations and past situations', [25,28], ['freetime','hello'], ['Accept or decline an invitation and arrange a meeting.', 'Use war and hatte for simple past explanations.'], 'Practise friendly question intonation and clear past verb forms.', 'Distinguish a meeting time from an activity start time.', 'Read an invitation and a reply.', 'Write a complete invitation or apology of about 30 words.', 'Invite a partner, answer their invitation and give a short reason.', 'Cover all requested content points in a message and negotiate a meeting orally.'),
  module(14, 'Yesterday and short journeys', [26,27], ['verbs','verbs2','travel'], ['Understand common Perfekt forms and describe completed actions.', 'Give a short account of a familiar journey.'], 'Say auxiliary and participle as one meaning unit; practise irregular participles aloud.', 'Separate past actions from future plans in a message.', 'Read a postcard or a short travel update.', 'Write four clear sentences about yesterday or a trip.', 'Ask and answer Was hast du gestern gemacht? and Wann bist du angekommen?', 'Use a small reliable past-tense repertoire; recognise common past forms in a new text.'),
  module(15, 'Reading and listening under exam conditions', [29,30], ['post','places','numbers','time'], ['Read short messages, select advertisements and interpret signs.', 'Find details in dialogues, public announcements and phone messages.'], 'Listen to several unfamiliar voices; practise number and time contrasts.', 'Complete the official-style 6/4/5 listening task sequence with its playback limits.', 'Complete 15 reading items in 25 minutes.', 'Keep an error log explaining why distractors were wrong.', 'Summarise a practical instruction and ask for clarification.', 'Reach at least 12/15 separately in unfamiliar listening and reading practice on two occasions.'),
  module(16, 'Writing, speaking and final rehearsal', [31,32], ['hello','alphabet','numbers','post','food','freetime'], ['Complete form fields and write a clear three-point short message.', 'Perform introduction, information exchange and request-response rounds.'], 'Focus on intelligibility, natural pauses and repair phrases; vary the practice partner.', 'Complete a full timed written rehearsal with official listening recordings.', 'Complete a full timed reading section and check the answer sheet.', 'Write at least three different messages and complete two unfamiliar forms.', 'Do all three speaking parts with a partner or tutor and obtain feedback.', 'Complete two different full rehearsals, aim for at least 80/100 with writing and speaking reviewed, and have no persistent task-completion gap.'),
];

